BEGIN
	IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'order_packs') THEN
		RAISE EXCEPTION 'migration 0117: order_packs already exists — this migration has already been applied.';
	END IF;
END $$;
