-- ── the post-migration assertion (the 0116 model, A5) ────────────────────
-- Made-up uuids. Each table has one valid base row; each shape merges an
-- override over it (`jsonb_populate_record`). The accepted shapes are
-- inserted and rolled back by a sentinel, so a CHECK that refused everything
-- fails the migration; each refused shape runs in its own subtransaction and
-- must be refused BY ITS NAMED CONSTRAINT (CHECKs run in name order, guide §3:
-- each probe violates only its target). `order_cartons_code_shape` is
-- shadowed by `order_cartons_code_derived` (a derived code always has the
-- shape), so its probes drop the derived CHECK inside their own
-- subtransaction, which the probe's exception rolls back (the 0098 pattern);
-- the pack-seq probe drops the shape CHECK the same way.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	base jsonb;
	rec jsonb;
	refused_by text;
	probe record;
	shape record;
BEGIN
	base := jsonb_build_object(
		'tenant_id', t, 'warehouse_id', gen_random_uuid(), 'client_id', gen_random_uuid(),
		'seq', 1, 'status', 'live', 'carton_count', 2, 'gross_weight_grams', 6000,
		'document_parties', '{"v":1,"client":{"name":"Brand"},"warehouse":{"code":"WH1","name":"Main"}}'::jsonb,
		'parties_frozen_at', now(), 'source', 'web', 'device_id', NULL,
		'packed_by', u, 'packed_at', now(), 'ended_at', NULL, 'ended_by', NULL, 'end_reason', NULL,
		'created_at', now(), 'updated_at', now());
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('a live pack with parties', '{}'),
			('a superseded pack with a reason', '{"status":"superseded","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%","end_reason":"Re-packed"}'),
			('a cancelled pack', '{"status":"cancelled","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%"}'),
			('a handheld pack with a device', '{"source":"handheld","device_id":"%R%","gross_weight_grams":null}'),
			('a re-carton pack', '{"source":"recarton","seq":2}')
		) AS s(name, override) LOOP
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid())
				|| replace(replace(shape.override, '%U%', u::text), '%R%', gen_random_uuid()::text)::jsonb;
			INSERT INTO "order_packs" SELECT (jsonb_populate_record(NULL::"order_packs", rec)).*;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0117', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0117: an accepted pack shape (%) was refused (%).', shape.name, SQLERRM;
		WHEN SQLSTATE 'P0117' THEN
			NULL;
	END;
	FOR probe IN SELECT * FROM (VALUES
		('an unknown status', 'order_packs_status_check', '{"status":"open","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%"}'),
		('seq 100', 'order_packs_seq_range', '{"seq":100}'),
		('seq 0', 'order_packs_seq_range', '{"seq":0}'),
		('zero cartons', 'order_packs_carton_count_range', '{"carton_count":0}'),
		('201 cartons', 'order_packs_carton_count_range', '{"carton_count":201}'),
		('a zero gross weight', 'order_packs_gross_weight_range', '{"gross_weight_grams":0}'),
		('a gross weight of 200,000,001', 'order_packs_gross_weight_range', '{"gross_weight_grams":200000001}'),
		('an unknown source', 'order_packs_source_check', '{"source":"fax"}'),
		('a handheld pack without a device', 'order_packs_device_pairing', '{"source":"handheld"}'),
		('a web pack with a device', 'order_packs_device_pairing', '{"device_id":"%R%"}'),
		('a live pack with ended_at', 'order_packs_end_pairing', '{"ended_at":"2026-10-30T00:00:00Z"}'),
		('a cancelled pack without its end', 'order_packs_end_pairing', '{"status":"cancelled"}'),
		('a live pack with only ended_by', 'order_packs_end_pairing', '{"ended_by":"%U%"}'),
		('a reason on a live pack', 'order_packs_end_reason', '{"end_reason":"x"}'),
		('a superseded pack without a reason', 'order_packs_end_reason', '{"status":"superseded","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%"}'),
		('an empty reason', 'order_packs_end_reason', '{"status":"superseded","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%","end_reason":""}'),
		('a 201-character reason', 'order_packs_end_reason', '{"status":"superseded","ended_at":"2026-10-30T00:00:00Z","ended_by":"%U%","end_reason":"%LONG%"}'),
		('parties v:2', 'order_packs_parties_shape', '{"document_parties":{"v":2,"client":{},"warehouse":{}}}'),
		('parties without a warehouse', 'order_packs_parties_shape', '{"document_parties":{"v":1,"client":{}}}'),
		('parties as an array', 'order_packs_parties_shape', '{"document_parties":[1]}'),
		('NULL parties', 'not-null:document_parties', '{"document_parties":null}')
	) AS p(name, expected, override) LOOP
		refused_by := NULL;
		BEGIN
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid())
				|| replace(replace(replace(probe.override, '%U%', u::text), '%R%', gen_random_uuid()::text), '%LONG%', repeat('x', 201))::jsonb;
			INSERT INTO "order_packs" SELECT (jsonb_populate_record(NULL::"order_packs", rec)).*;
			RAISE EXCEPTION USING ERRCODE = 'P0117', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN not_null_violation THEN
				GET STACKED DIAGNOSTICS refused_by = COLUMN_NAME;
				refused_by := 'not-null:' || refused_by;
			WHEN SQLSTATE 'P0117' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0117: pack probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	-- One live pack per order.
	BEGIN
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', u);
		INSERT INTO "order_packs" SELECT (jsonb_populate_record(NULL::"order_packs", rec)).*;
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', u, 'seq', 2);
		INSERT INTO "order_packs" SELECT (jsonb_populate_record(NULL::"order_packs", rec)).*;
		RAISE EXCEPTION USING ERRCODE = 'P0117', MESSAGE = 'two live packs landed';
	EXCEPTION
		WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			IF refused_by IS DISTINCT FROM 'order_packs_live_unique' THEN
				RAISE EXCEPTION 'migration 0117: a second live pack was refused by % (expected order_packs_live_unique).', refused_by;
			END IF;
		WHEN SQLSTATE 'P0117' THEN
			RAISE EXCEPTION 'migration 0117: two live packs of one order were accepted.';
	END;
	IF EXISTS (SELECT 1 FROM "order_packs" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0117: a pack probe row survived.';
	END IF;
END $$;
--> statement-breakpoint
DO $$
DECLARE
	t uuid := gen_random_uuid();
	o uuid;
	base jsonb;
	rec jsonb;
	refused_by text;
	probe record;
	shape record;
BEGIN
	base := jsonb_build_object(
		'tenant_id', t, 'warehouse_id', gen_random_uuid(), 'client_id', gen_random_uuid(),
		'pack_id', gen_random_uuid(), 'pack_seq', 1, 'seq', 1, 'code', '%D%',
		'weight_grams', 3200, 'length_mm', NULL, 'width_mm', NULL, 'height_mm', NULL,
		'unit_count', 10000, 'line_count', 1, 'handover_id', NULL, 'handover_scanned_at', NULL,
		'created_at', now());
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('a weighed carton', '{}'),
			('a carton with all three dims', '{"length_mm":400,"width_mm":300,"height_mm":200}'),
			('an unmeasured carton of pack 99, carton 200', '{"weight_grams":null,"pack_seq":99,"seq":200}'),
			('a carton scanned at a handover', '{"handover_id":"%R%","handover_scanned_at":"2026-10-30T00:00:00Z"}')
		) AS s(name, override) LOOP
			o := gen_random_uuid();
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'pack_id', gen_random_uuid())
				|| replace(shape.override, '%R%', gen_random_uuid()::text)::jsonb;
			IF rec->>'code' = '%D%' THEN
				rec := rec || jsonb_build_object('code', 'O' || upper(right(replace(o::text, '-', ''), 16)) || '.' || (rec->>'pack_seq') || '.' || (rec->>'seq'));
			END IF;
			INSERT INTO "order_cartons" SELECT (jsonb_populate_record(NULL::"order_cartons", rec)).*;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0117', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0117: an accepted carton shape (%) was refused (%).', shape.name, SQLERRM;
		WHEN SQLSTATE 'P0117' THEN
			NULL;
	END;
	FOR probe IN SELECT * FROM (VALUES
		('a code with a hyphen', 'order_cartons_code_shape', 'order_cartons_code_derived', '{"code":"O0123456789ABCDEF-1-1"}'),
		('a code with a leading zero', 'order_cartons_code_shape', 'order_cartons_code_derived', '{"code":"O0123456789ABCDEF.01.1"}'),
		('a code naming another order', 'order_cartons_code_derived', NULL, '{"code":"O0123456789ABCDEF.1.1"}'),
		('a code naming another pack seq', 'order_cartons_code_derived', NULL, '{"code":"%T%.2.1"}'),
		('carton 201', 'order_cartons_seq_range', NULL, '{"seq":201}'),
		('carton 0', 'order_cartons_seq_range', 'order_cartons_code_shape', '{"seq":0}'),
		('pack seq 100', 'order_cartons_pack_seq_range', 'order_cartons_code_shape', '{"pack_seq":100}'),
		('pack seq 0', 'order_cartons_pack_seq_range', 'order_cartons_code_shape', '{"pack_seq":0}'),
		('a zero weight', 'order_cartons_weight_range', NULL, '{"weight_grams":0}'),
		('a weight of 1,000,001', 'order_cartons_weight_range', NULL, '{"weight_grams":1000001}'),
		('a dim of 100,001', 'order_cartons_dims', NULL, '{"length_mm":100001,"width_mm":300,"height_mm":200}'),
		('two dims of three', 'order_cartons_dims', NULL, '{"length_mm":400,"width_mm":300}'),
		('a zero dim', 'order_cartons_dims', NULL, '{"length_mm":400,"width_mm":0,"height_mm":200}'),
		('a zero-unit carton', 'order_cartons_units_positive', NULL, '{"unit_count":0}'),
		('a carton of no lines', 'order_cartons_line_count_range', NULL, '{"line_count":0}'),
		('a carton of 501 lines', 'order_cartons_line_count_range', NULL, '{"line_count":501}'),
		('a handover without its instant', 'order_cartons_handover_pairing', NULL, '{"handover_id":"%R%"}')
	) AS p(name, expected, shadow, override) LOOP
		refused_by := NULL;
		BEGIN
			IF probe.shadow IS NOT NULL THEN
				EXECUTE format('ALTER TABLE "order_cartons" DROP CONSTRAINT %I', probe.shadow);
			END IF;
			o := gen_random_uuid();
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'pack_id', gen_random_uuid())
				|| replace(replace(probe.override, '%R%', gen_random_uuid()::text), '%T%', 'O' || upper(right(replace(o::text, '-', ''), 16)))::jsonb;
			IF rec->>'code' = '%D%' THEN
				rec := rec || jsonb_build_object('code', 'O' || upper(right(replace(o::text, '-', ''), 16)) || '.' || (rec->>'pack_seq') || '.' || (rec->>'seq'));
			END IF;
			INSERT INTO "order_cartons" SELECT (jsonb_populate_record(NULL::"order_cartons", rec)).*;
			RAISE EXCEPTION USING ERRCODE = 'P0117', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0117' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0117: carton probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	-- The shadow drops rolled back with their probes.
	IF (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.order_cartons'::regclass AND contype = 'c'
	      AND conname IN ('order_cartons_code_shape', 'order_cartons_code_derived') AND convalidated) <> 2 THEN
		RAISE EXCEPTION 'migration 0117: the carton code CHECKs did not survive their probes.';
	END IF;
	-- A code names one carton.
	BEGIN
		o := gen_random_uuid();
		rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', o, 'code', 'O' || upper(right(replace(o::text, '-', ''), 16)) || '.1.1');
		INSERT INTO "order_cartons" SELECT (jsonb_populate_record(NULL::"order_cartons", rec)).*;
		rec := rec || jsonb_build_object('id', gen_random_uuid(), 'pack_id', gen_random_uuid());
		INSERT INTO "order_cartons" SELECT (jsonb_populate_record(NULL::"order_cartons", rec)).*;
		RAISE EXCEPTION USING ERRCODE = 'P0117', MESSAGE = 'two cartons on one code landed';
	EXCEPTION
		WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			IF refused_by IS DISTINCT FROM 'order_cartons_tenant_code_unique' THEN
				RAISE EXCEPTION 'migration 0117: a duplicate carton code was refused by % (expected order_cartons_tenant_code_unique).', refused_by;
			END IF;
		WHEN SQLSTATE 'P0117' THEN
			RAISE EXCEPTION 'migration 0117: two cartons on one code were accepted.';
	END;
	IF EXISTS (SELECT 1 FROM "order_cartons" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0117: a carton probe row survived.';
	END IF;
END $$;
